// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/import", wrapper.ImportProfiles)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/inventory", wrapper.GetInventory)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/logs", wrapper.GetLogs)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/probe", wrapper.ProbeProfiles)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/profiles/{id}", wrapper.DeleteProfile)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/profiles/{id}/activate", wrapper.ActivateProfile)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/profiles/{id}/config", wrapper.GetConfig)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/profiles/{id}/config", wrapper.UpdateConfig)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/router", wrapper.GetRouterDashboard)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/router/external-check", wrapper.CheckExternal)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/settings/dns", wrapper.GetDNSSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/settings/dns", wrapper.PutDNSSettings)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/settings/routing", wrapper.GetRoutingSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/settings/routing", wrapper.PutRoutingSettings)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/settings/zapret", wrapper.GetZapretSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/settings/zapret", wrapper.PutZapretSettings)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/status", wrapper.GetStatus)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/subscriptions/{id}", wrapper.DeleteSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/subscriptions/{id}/refresh", wrapper.RefreshSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/update", wrapper.GetPanelUpdate)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/update", wrapper.InstallPanelUpdate)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/xray/profile", wrapper.ClearXrayProfile)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/xray/restart", wrapper.RestartXray)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/xray/stop", wrapper.StopXray)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/zapret", wrapper.GetZapretStatus)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/zapret", wrapper.ManageZapret)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/zapret/probe", wrapper.ProbeZapret)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/zapret/strategies", wrapper.GetZapretStrategies)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/zapret/strategies", wrapper.PutZapretStrategies)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/zapret/tune", wrapper.TuneZapret)
	})

	return r
}
